namespace ghidra.feature.vt.gui.actions;



using docking;
using docking.action;
using docking.tool;
using docking.widgets;
using docking.wizard;
using generic.theme;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.wizard.session;
using ghidra.util;

public class CreateVersionTrackingSessionAction : DockingAction {
	public static Icon NEW_ICON = new GIcon("icon.version.tracking.action.create.session");
	private VTController controller;

	public CreateVersionTrackingSessionAction(VTController controller) : base("Create New Session", VTPlugin.OWNER)
    {
		this.controller = controller;
		string[] menuPath = new string[] { ToolConstants.MENU_FILE, "New Session..." };
		setMenuBarData(new MenuData(menuPath, NEW_ICON, "AAA"));
		setToolBarData(new ToolBarData(NEW_ICON, "View"));
		setDescription("Creates a new Version Tracking Session");
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Create_Session"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		if (controller.getSession() != null) {
			int result =
				OptionDialog.showYesNoDialog(controller.getTool().getToolFrame(),
					"Create New Session",
					"This will close the current session.  Do you want to continue?");

			if (result != OptionDialog.YES_OPTION) {
				return;
			}
		}
		if (!controller.closeVersionTrackingSession()) {
			return; // user cancelled  during save dialog
		}
		VTNewSessionWizardModel model = new VTNewSessionWizardModel(controller);
		WizardDialog wizardDialog = new WizardDialog(model);
		wizardDialog.show(controller.getParentComponent());
	}

}
